records.command:
mkdir -p classic/apps/web/src/export/queue classic/apps/web/src/app/api/render-queue/file classic/apps/web/src/app/render-queue
cat > classic/apps/web/src/export/queue/types.ts <<'EOF'
import type { CanonicalClassicSnapshot } from "@/core/canonical-classic-session";
import type { ExportOptions } from "@/export";
export type RenderJob = {
 id: string; projectId: string; sceneId: string; sourceRevision: number;
 snapshot: CanonicalClassicSnapshot; snapshotHash: string;
 options: Required<ExportOptions>; status: "queued"|"rendering"|"completed"|"failed"|"cancelled";
 createdAtMs: number; updatedAtMs: number; progress: number; message: string;
 attempt: string|null; cancelRequested: boolean; outputId: string|null;
};
export type RenderJobView = Omit<RenderJob,"snapshot"|"attempt"> & {projectName:string;sceneName:string};
export type RenderQueueView = { revision:number; jobs:RenderJobView[] };
EOF
cat > classic/apps/web/src/export/queue/server.ts <<'EOF'
/** Host IO only. Every queue transition is executed by OpenCutRuntime. */
import { mkdir, readFile, writeFile, rename, unlink, stat, link, copyFile, open } from "node:fs/promises";
import { join } from "node:path";
import { randomUUID } from "node:crypto";
import lockfile from "proper-lockfile";
import { accountDataRoot } from "@/accounts/server";
import { getMediaFile, getFontFile, getProject } from "@/services/local-drive/server";
import type { CanonicalEditorRuntime } from "opencut-editor-runtime-wasm";
import type { RenderJob, RenderQueueView } from "./types";
import type { CanonicalClassicSnapshot } from "@/core/canonical-classic-session";
import type { ExportOptions } from "@/export";
type State = {revision:number;renderQueue:RenderJob[]};
type Source = {id:string;path:string;size:number;mtimeMs:number;mimeType:string;kind:"media"|"font"};
const root = () => join(accountDataRoot(),"render-queue");
const valid = (s:string) => {if(!/^[a-zA-Z0-9_-]{1,160}$/.test(s)) throw Error("Invalid render identity");return s;};

